from typing import List

class Solution:
    def maxWeight(self, pizzas: List[int]) -> int:
        pizzas.sort()
        days = len(pizzas) // 4
        odd_days = (days + 1) // 2
        even_days = days // 2

        total = sum(pizzas[-odd_days:])

        idx = len(pizzas) - odd_days - 2
        for _ in range(even_days):
            total += pizzas[idx]
            idx -= 2

        return total
